**Step 2: Code-behind pattern (.ascx.cs)**

```csharp
using System;
using System.Data;
using SimsObject;
using WebGlobal;

namespace InformationWeb.Controls.Learning
{
    public partial class MyControl : ControlBase  // <-- inherits ControlBase
    {
        private const string PERMISSION_VIEW = "frmWebMyPage_View";

        // Private DataTable storage
        private DataTable dtbData = null;

        // ViewState-backed properties
        private string SortBy
        {
            set { ViewState["SortBy" + this.ClientID] = value; }
            get { return ViewState["SortBy" + this.ClientID] as string; }
        }

        // Load data using SIM_Branch
        private void LoadData()
        {
            SIM_Branch obj = new SIM_Branch();
            dtbData = obj.GetDataTable("STORED_PROC_NAME",
                "@ClassID", uClass.ClassID,
                "@YearID", uYearSemester.YearID,
                "@Semester", uYearSemester.Semester);
            // ... process data, build HTML table, set lblContent.Text
        }

        // Validation
        private bool IsValidData(bool isShowMsg = true)
        {
            if (uClass.ClassID == null)
            {
                if (isShowMsg) MsgBox.ShowWarning("Ban phai chon lop hoc!");
                return false;
            }
            return true;
        }

        // Page lifecycle
        protected void Page_Load(object sender, EventArgs e)
        {
            uYearSemester.EditValueChanged += uYearSemester_EditValueChanged;
            uClass.SelectedChanged += uClass_SelectedChanged;

            if (!IsPostBack)
            {
                if (User == null || !WebGlobal.HasPermission(PERMISSION_VIEW))
                {
                    MsgBox.ShowWarning("Ban khong co quyen truy cap chuc nang nay!");
                    this.Visible = false;
                    return;
                }
                uClass.PermissionID = PERMISSION_VIEW;
                uClass.ManagerTeacherID = User.UserName;
                uClass.LoadData();
            }
        }

        // Event handlers
        protected void btnSearch_Click(object sender, EventArgs e)
        {
            if (IsValidData()) LoadData();
        }

        protected void btnExportExcel_Click(object sender, EventArgs e)
        {
            ExportExcel(); // same Libs.CExcel pattern shown above
        }

        private void uYearSemester_EditValueChanged(object yearID, object semester)
        {
            if (IsValidData(false)) LoadData();
        }

        private void uClass_SelectedChanged(object sender, EventArgs e)
        {
            if (IsValidData(false)) LoadData();
        }
    }
}
```

